from taf.gnb.oam.coam.vdu.utilities.http_client import HttpClient


class CPConfigLicensedV1HttpClient(HttpClient):
    """ This class provides a client for the CP Config Licensed V1 API. """

    def __init__(self, base_url, connection_alias):
        super(CPConfigLicensedV1HttpClient, self).__init__(connection_alias)
        self.base_url = base_url + "/api/licensed/v1"

    def reset_vdu(self, timeout=60, graceful_cell_shutdown=False):
        endpoint = '/vdu/operations/resets'
        headers = {
            "Content-Type": "application/json",
        }

        payload = {
            "gracefulCellShutdown": "true" if graceful_cell_shutdown else "false"
        }

        return self._send_post_request(endpoint=endpoint, timeout=timeout, headers=headers, json=payload)

    def get_reset_vdu_operation_status(self, operation_id, timeout=30):
        endpoint = f'/vdu/operations/resets/{operation_id}'
        return self._send_get_request(endpoint=endpoint, timeout=timeout)

    def start_rf_diagnostic_test(self, nr_cell_id, act_remote_rf_diag=True, rx_antenna_rssi_high_threshold=-30,
                                 rx_antenna_rssi_low_threshold=-110, tx_antenna_vswr_high_threshold=3,
                                 rx_antenna_rtwp_high_threshold=0, rx_antenna_rtwp_low_threshold=0):
        endpoint = "/diagnostic/rf-diagnostic-test"
        headers = {
            "Content-Type": "application/json",
        }

        payload = {
          "targetCellId": nr_cell_id,
          "actRemoteRfDiag": act_remote_rf_diag,
          "thresholds": {
            "rxAntennaRSSIHighThreshold": rx_antenna_rssi_high_threshold,
            "rxAntennaRSSILowThreshold": rx_antenna_rssi_low_threshold,
            "txAntennaVSWRHighThreshold": tx_antenna_vswr_high_threshold,
            "rxAntennaRTWPHighThreshold": rx_antenna_rtwp_high_threshold,
            "rxAntennaRTWPLowThreshold": rx_antenna_rtwp_low_threshold
          }
        }

        return self._send_post_request(endpoint=endpoint, headers=headers, json=payload)

    def get_status_of_start_rf_diagnostic_test_operation(self, operation_id, timeout=30):
        endpoint = f"/diagnostic/rf-diagnostic-test/{operation_id}"
        return self._send_get_request(endpoint=endpoint, timeout=timeout)

    def block_cell(self, cell_id, timeout=60):
        endpoint = '/cells/operations/block'
        headers = {
            "Content-Type": "application/json",
        }

        payload = {
            "id": cell_id
        }

        return self._send_post_request(endpoint=endpoint, timeout=timeout, headers=headers, json=payload)

    def unblock_cell(self, cell_id, timeout=60):
        endpoint = '/cells/operations/unblock'
        headers = {
            "Content-Type": "application/json",
        }

        payload = {
            "id": cell_id
        }

        return self._send_post_request(endpoint=endpoint, timeout=timeout, headers=headers, json=payload)

    def get_operation_of_reset_cell_group(self, operation_id, timeout=30):
        endpoint = f'/cell-groups/operations/resets/{operation_id}'
        headers = {
            "Content-Type": "application/json",
        }
        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def delete_block(self, operation_id, timeout=30):
        endpoint = f'/cells/operations/block/{operation_id}'
        headers = {
            "Content-Type": "application/json",
        }

        self._send_delete_request(endpoint=endpoint, timeout=timeout, headers=headers)

    def get_diagnostic_rf_diagnostic_test_results(self, timeout=30):
        endpoint = '/diagnostic/rf-diagnostic-test/results'
        headers = {
            "Content-Type": "application/json",
        }
        return self._send_get_request(endpoint=endpoint, timeout=timeout, headers=headers)
